package io.github.pixelsuite;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.view.animation.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

final class IconPackPage {
 private static final ExecutorService WORK=Executors.newFixedThreadPool(2);
 private static String lastPackage,lastLabel;
 private final Activity activity;private final TextView summary;private final int ink,muted,accent;
 private final Handler main=new Handler(Looper.getMainLooper());
 private final ArrayList<IconPacks.Info> packs=new ArrayList<IconPacks.Info>();
 private final Map<String,Details> details=new HashMap<String,Details>();private final Set<String> loading=new HashSet<String>(),revealed=new HashSet<String>();
 private Sheet panel;private LinearLayout content;private ListView list;private TextView status;private PacksAdapter adapter;
 private String selected="";private boolean disposed,registered,saving,selectedKnown;private int generation,selectionRevision;
 private final BroadcastReceiver packages=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.getData()!=null)IconPacks.forget(i.getData().getSchemeSpecificPart());reload();}};
 private static final class Details {Drawable icon;List<Drawable> preview;String count;}
 IconPackPage(Activity a,TextView value,int ink,int muted,int accent){activity=a;summary=value;this.ink=ink;this.muted=muted;this.accent=accent;if(lastLabel!=null)summary.setText(lastLabel);if(lastPackage!=null){selected=lastPackage;selectedKnown=true;}refresh();}
 private int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private boolean live(){return !disposed&&!activity.isFinishing()&&!activity.isDestroyed();}
 void refresh(){final int revision=selectionRevision;WORK.execute(new Runnable(){public void run(){final List<String> stored=Root.run("settings get secure "+IconPacks.KEY);if(stored==null||stored.isEmpty())return;final String pkg="null".equals(stored.get(0))?"":stored.get(0);String label="System default";if(!pkg.isEmpty())try{label=activity.getPackageManager().getApplicationLabel(activity.getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception missing){}final String name=label;main.post(new Runnable(){public void run(){if(!live()||revision!=selectionRevision)return;selectedKnown=true;selected=pkg;lastPackage=pkg;lastLabel=name;summary.setText(name);if(adapter!=null)adapter.notifyDataSetChanged();}});}});}
 void show(){if(panel!=null||!live())return;panel=new Sheet();content=new LinearLayout(activity);content.setOrientation(1);content.setPadding(dp(16),dp(12),dp(16),dp(12));content.setBackground(AppSurfaces.sheet(activity,28));content.setClipToOutline(true);
  LinearLayout header=new LinearLayout(activity);header.setOrientation(1);header.setGravity(Gravity.CENTER_HORIZONTAL);
  View handle=new View(activity);GradientDrawable grip=new GradientDrawable();grip.setColor(muted);grip.setCornerRadius(dp(2));handle.setBackground(grip);header.addView(handle,new LinearLayout.LayoutParams(dp(34),dp(4)));
  LinearLayout titleRow=new LinearLayout(activity);titleRow.setGravity(Gravity.CENTER_VERTICAL);TextView title=label("Icon pack",24,ink);title.setPadding(dp(4),dp(18),0,dp(12));titleRow.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView close=label("×",26,muted);close.setGravity(Gravity.CENTER);AppCloseButton.style(close);close.setContentDescription("Close icon packs");titleRow.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));close.setOnClickListener(v->panel.dismiss());header.addView(titleRow,new LinearLayout.LayoutParams(-1,-2));content.addView(header);
  final float[] down={0};header.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){down[0]=e.getRawY();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){content.setTranslationY(Math.max(0,e.getRawY()-down[0]));return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){if(e.getActionMasked()!=MotionEvent.ACTION_CANCEL&&content.getTranslationY()>dp(64))panel.dismiss();else content.animate().translationY(0).setDuration(AppMotion.enabled(activity)?220:0).setInterpolator(new PathInterpolator(.2f,0,0,1)).start();return true;}return true;});
  status=label("Loading icon packs…",14,muted);status.setPadding(dp(4),dp(4),dp(4),dp(8));content.addView(status);
  list=new ListView(activity);ToastMotion.watchScroll(list);list.setDivider(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));list.setDividerHeight(dp(10));list.setBackgroundColor(Color.TRANSPARENT);adapter=new PacksAdapter();list.setAdapter(adapter);content.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((parent,row,pos,id)->choose(pos==0?"":packs.get(pos-1).pkg,pos==0?"System default":packs.get(pos-1).label,row));
  TextView note=label("Apps the pack doesn't include keep their own icons. Change one app's icon: long-press it > Change icon > Icon pack.",12,muted);note.setPadding(dp(4),dp(10),dp(4),dp(4));content.addView(note);
  panel.setContentView(content);panel.setCanceledOnTouchOutside(true);panel.setOnDismissListener(d->{unregister();generation++;panel=null;adapter=null;list=null;status=null;content=null;});panel.show();Window w=panel.getWindow();if(w!=null){w.setWindowAnimations(0);w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);AppSurfaces.dim(w,.42f);AppPanelBounds.fit(activity,w,(int)(activity.getResources().getDisplayMetrics().heightPixels*.75f));if(FrostedSurface.blurEnabled(activity)&&!AppSurfaces.active(activity))try{WindowManager.LayoutParams lp=w.getAttributes();lp.getClass().getMethod("setBlurBehindRadius",int.class).invoke(lp,dp(20));lp.flags|=4;w.setAttributes(lp);}catch(Exception ignored){}}
  content.setOnApplyWindowInsetsListener((v,in)->{content.setPadding(dp(16)+in.getSystemWindowInsetLeft(),dp(12),dp(16)+in.getSystemWindowInsetRight(),dp(12)+in.getSystemWindowInsetBottom());return in;});content.requestApplyInsets();content.setTranslationY(dp(48));content.setAlpha(0);content.animate().translationY(0).alpha(1).setDuration(AppMotion.enabled(activity)?350:0).setInterpolator(new PathInterpolator(.05f,.7f,.1f,1)).start();register();reload();
 }
 private void register(){IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_PACKAGE_ADDED);f.addAction(Intent.ACTION_PACKAGE_REMOVED);f.addAction(Intent.ACTION_PACKAGE_REPLACED);f.addDataScheme("package");try{if(Build.VERSION.SDK_INT>=33)Context.class.getMethod("registerReceiver",BroadcastReceiver.class,IntentFilter.class,int.class).invoke(activity,packages,f,4);else activity.registerReceiver(packages,f);registered=true;}catch(Exception ignored){}}
 private void unregister(){if(registered){activity.unregisterReceiver(packages);registered=false;}}
 void dispose(){disposed=true;generation++;unregister();if(panel!=null)panel.closeNow();}
 private void reload(){if(panel==null||!live())return;final int request=++generation;details.clear();loading.clear();revealed.clear();status.setText("Loading icon packs…");WORK.execute(()->{final List<IconPacks.Info> found=IconPacks.installed(activity);main.post(()->{if(!live()||panel==null||request!=generation)return;packs.clear();packs.addAll(found);status.setText(found.isEmpty()?"No icon packs installed yet":found.size()+" icon packs");adapter.notifyDataSetChanged();});});}
 private void choose(final String pkg,final String title,View row){if(saving||!live()||!pkg.isEmpty()&&!pkg.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))return;saving=true;selectionRevision++;final String previous=selected;final boolean previousKnown=selectedKnown;selectedKnown=true;selected=pkg;adapter.notifyDataSetChanged();row.setScaleX(.92f);row.setScaleY(.92f);row.animate().scaleX(1).scaleY(1).setDuration(AppMotion.enabled(activity)?250:0).setInterpolator(new OvershootInterpolator(.55f)).start();final long start=SystemClock.uptimeMillis();WORK.execute(()->{final boolean ok=Root.run(pkg.isEmpty()?"settings delete secure "+IconPacks.KEY:"settings put secure "+IconPacks.KEY+" '"+pkg+"'")!=null;main.postDelayed(()->{saving=false;if(!live())return;if(ok){lastPackage=selected=pkg;lastLabel=title;summary.setText(title);if(panel!=null)panel.dismiss();}else{selected=previous;selectedKnown=previousKnown;if(adapter!=null)adapter.notifyDataSetChanged();AppToast.makeText(activity,"Couldn't save: root access needed",Toast.LENGTH_SHORT).show();}},Math.max(0,250-(SystemClock.uptimeMillis()-start)));});}
 private TextView label(String text,int size,int color){TextView t=new TextView(activity);t.setText(SettingsText.format(text));t.setTextSize(size);t.setTextColor(color);return t;}
 private void fetch(final String pkg){if(!loading.add(pkg))return;final int request=generation;WORK.execute(()->{final Details d=new Details();try{d.icon=activity.getPackageManager().getApplicationIcon(pkg);IconPacks.Pack pack=IconPacks.get(activity,pkg);d.count=String.format(java.util.Locale.getDefault(),"%,d icons",pack==null?0:pack.all.size());d.preview=IconPacks.preview(activity,pkg,4);}catch(Exception unavailable){d.count="Unavailable";d.preview=Collections.emptyList();}main.post(()->{if(!live()||panel==null||generation!=request)return;details.put(pkg,d);adapter.notifyDataSetChanged();});});}
 private final class PacksAdapter extends BaseAdapter {
  public int getCount(){return packs.size()+1+(packs.isEmpty()?1:0);}public Object getItem(int pos){return pos;}public long getItemId(int pos){return pos;}
  public boolean isEnabled(int pos){return pos<=packs.size();}
  public View getView(int pos,View reuse,ViewGroup parent){
   if(pos>packs.size()){TextView get=label("Get icon packs",16,accent);get.setPadding(dp(18),dp(14),dp(18),dp(14));get.setGravity(Gravity.CENTER);get.setBackground(AppSurfaces.field(activity,24));get.setOnClickListener(v->{try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("market://search?q=icon%20pack&c=apps")));}catch(Exception unavailable){activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://play.google.com/store/search?q=icon%20pack&c=apps")));}});return get;}
   final String pkg=pos==0?"":packs.get(pos-1).pkg;LinearLayout row=new LinearLayout(activity);row.setOrientation(1);row.setPadding(dp(12),dp(12),dp(12),dp(12));boolean checked=selectedKnown&&pkg.equals(selected);GradientDrawable bg=AppSurfaces.field(activity,18);if(checked)bg.setStroke(dp(1.5f),accent);row.setBackground(bg);
   LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(activity);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(40),dp(40));ip.rightMargin=dp(12);top.addView(icon,ip);LinearLayout words=new LinearLayout(activity);words.setOrientation(1);words.addView(label(pos==0?"System default":packs.get(pos-1).label,17,ink));TextView count=label(pos==0?"Pixel Launcher's own icons, including themed icons":"Loading icons…",12,muted);words.addView(count);top.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView check=label(checked?"✓":"",22,accent);check.setGravity(Gravity.CENTER);top.addView(check,new LinearLayout.LayoutParams(dp(32),dp(40)));row.addView(top);
   if(pos==0){icon.setImageResource(activity.getResources().getIdentifier("ic_ps_themes","drawable",activity.getPackageName()));icon.setColorFilter(accent);}else{Details d=details.get(pkg);if(d==null)fetch(pkg);else{if(d.icon!=null)icon.setImageDrawable(d.icon.getConstantState()==null?d.icon:d.icon.getConstantState().newDrawable().mutate());count.setText(d.count);LinearLayout previews=new LinearLayout(activity);previews.setPadding(dp(52),dp(10),0,0);for(Drawable art:d.preview){ImageView image=new ImageView(activity);image.setImageDrawable(art.getConstantState()==null?art:art.getConstantState().newDrawable().mutate());LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(36),dp(36));pp.rightMargin=dp(10);previews.addView(image,pp);}row.addView(previews);if(revealed.add(pkg)){previews.setAlpha(0);previews.animate().alpha(1).setDuration(AppMotion.enabled(activity)?220:0).start();}row.setTag(pkg);}}
   row.setContentDescription((pos==0?"System default":packs.get(pos-1).label)+(checked?", selected":""));return row;
  }
 }
 private final class Sheet extends Dialog {boolean closing;Sheet(){super(activity);requestWindowFeature(Window.FEATURE_NO_TITLE);}@Override public void cancel(){dismiss();}@Override public void dismiss(){if(closing)return;closing=true;if(content==null||!AppMotion.enabled(activity)){closeNow();return;}content.animate().cancel();content.animate().translationY(dp(60)).alpha(0).setDuration(240).setInterpolator(new PathInterpolator(.3f,0,.8f,.15f)).withEndAction(()->closeNow()).start();}void closeNow(){super.dismiss();}}
}
